import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

public class DatasetUtilities_iterateRangeBounds_TriageGen2Test {

    @Mock
    private XYDataset mockXYDataset;

    @Mock
    private IntervalXYDataset mockIntervalDataset;

    @Mock
    private OHLCDataset mockOHLCDataset;

    public DatasetUtilities_iterateRangeBounds_TriageGen2Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testStandardXYDataset_NormalValues() {
        when(mockXYDataset.getSeriesCount()).thenReturn(2);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getItemCount(1)).thenReturn(1);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(10.0);
        when(mockXYDataset.getYValue(1, 0)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(20.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testStandardXYDataset_WithNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(mockXYDataset.getYValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertEquals(5.0, result.getLower(), 1e-10);
        assertEquals(5.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testStandardXYDataset_Empty() {
        when(mockXYDataset.getSeriesCount()).thenReturn(0);
        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);
        assertNull(result);
    }

    @Test
    public void testIntervalXYDataset_IncludeInterval_True() {
        // Note: The code has a potential bug/feature where the loop starts at series = 1
        // for IntervalXYDataset. We test according to the provided logic.
        when(mockIntervalDataset.getSeriesCount()).thenReturn(3);
        when(mockIntervalDataset.getItemCount(1)).thenReturn(1);
        when(mockIntervalDataset.getItemCount(2)).thenReturn(1);

        // Series 1
        when(mockIntervalDataset.getYValue(1, 0)).thenReturn(15.0);
        when(mockIntervalDataset.getStartYValue(1, 0)).thenReturn(12.0);
        when(mockIntervalDataset.getEndYValue(1, 0)).thenReturn(18.0);

        // Series 2
        when(mockIntervalDataset.getYValue(2, 0)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getStartYValue(2, 0)).thenReturn(5.0);
        when(mockIntervalDataset.getEndYValue(2, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalDataset, true);

        assertEquals(5.0, result.getLower(), 1e-10);
        assertEquals(18.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIntervalXYDataset_IncludeInterval_False_FallsToStandard() {
        // If includeInterval is false, it should treat IntervalXYDataset as standard XYDataset
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalDataset.getYValue(0, 0)).thenReturn(100.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalDataset, false);

        assertEquals(100.0, result.getLower(), 1e-10);
        assertEquals(100.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testOHLCDataset_IncludeInterval_True() {
        when(mockOHLCDataset.getSeriesCount()).thenReturn(1);
        when(mockOHLCDataset.getItemCount(0)).thenReturn(2);

        // Item 0
        when(mockOHLCDataset.getLowValue(0, 0)).thenReturn(10.0);
        when(mockOHLCDataset.getHighValue(0, 0)).thenReturn(50.0);

        // Item 1
        when(mockOHLCDataset.getLowValue(0, 1)).thenReturn(Double.NaN);
        when(mockOHLCDataset.getHighValue(0, 1)).thenReturn(60.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockOHLCDataset, true);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(60.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testOHLCDataset_IncludeInterval_False_FallsToStandard() {
        // If includeInterval is false, it uses standard XYDataset logic (getYValue)
        when(mockOHLCDataset.getSeriesCount()).thenReturn(1);
        when(mockOHLCDataset.getItemCount(0)).thenReturn(1);
        when(mockOHLCDataset.getYValue(0, 0)).thenReturn(25.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockOHLCDataset, false);

        assertEquals(25.0, result.getLower(), 1e-10);
        assertEquals(25.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testAllNaNs_ReturnsNull() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);
        assertNull(result);
    }
}
